export type Balance = { "available_by_source_type"?: Record<string, SignedMoney>; /** Signed monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "available_money": { /** Signed amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "balance_id": string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; "held_by_type"?: Record<string, MoneyValue>; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "held_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "merchant_id": string; "payouts_enabled": boolean; "pending_by_source_type"?: Record<string, SignedMoney>; /** Signed monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "pending_money": { /** Signed amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "reserve_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "unavailable_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; };
